{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles relocation assistance for no-fault evictions under the RSO and JCO","requirement":"For a no-fault eviction of a tenant in an RSO- or JCO-covered unit, the landlord must file a Declaration of Intent to Evict with LAHD before serving notice and pay relocation assistance within 15 days of service.","key_value":"$11,000-$27,400 per unit (July 1, 2026-June 30, 2027)","coverage_conditions":"All units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO) in the City of Los Angeles.","applicability":{"conditions":[],"per_tenancy":"Amount depends on tenant status (qualified, eligible or low income) and length of tenancy; applies on a no-fault termination.","coverage_quotes":["All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO)."]},"exemptions":"Resident-manager replacement; eviction required by a natural-disaster hazard not caused by the landlord's negligence; landlord may offset the tenant's accumulated rent. Mom and Pop properties (four or fewer units) pay reduced amounts for owner, family or manager occupancy.","penalty":"Failure to file the Landlord Declaration makes the eviction a violation of the RSO or JCO; a tenant may raise non-payment of relocation assistance as an affirmative defense.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.); Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Resident Protections Ordinance relocation for demolition of Protected Units","requirement":"An owner demolishing a Protected Unit for new construction must file a declaration or notice with LAHD, serve the relocation notice, and pay enhanced relocation assistance to lower-income tenants rather than the standard RSO or JCO amounts.","key_value":"$250,000 per displaced unit","coverage_conditions":"Protected Units demolished for the purpose of new construction: rent-restricted, rent-controlled (including all RSO units), lower-income-occupied within the past five years, or Ellis Act withdrawn within the past ten years.","applicability":{"conditions":[{"type":"other","role":"covered","text":"only Protected Units demolished for the purpose of new construction"}],"per_tenancy":"Applies to demolition of a Protected Unit that is occupied; lower income tenants get enhanced amounts.","coverage_quotes":["The RPO only applies to Protected Units that will be demolished for the purpose of new construction."]},"exemptions":"Units that are not Protected Units or are not occupied by a lower income tenant receive the regular RSO or JCO relocation amounts instead of the RPO-enhanced amounts.","penalty":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","valid_through":null,"citation":"Los Angeles Resident Protections Ordinance (L.A. Ordinances #188481, #188482)","quoted_span":"Owners who demolish a Protected Unit for the purpose of new construction within 5 years after the filing of the Notice of Intent to Withdraw or Declaration of Intent to Evict with LAHD are required to comply with relocation requirements under the RPO.","interaction":"Owner must pay the higher of State HCA or City relocation amounts; RSO/JCO amounts must be enhanced for lower income tenants under the HCA.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
